"use client";

import "./command.css";
import { Dialog as BaseDialog } from "@base-ui/react/dialog";
import { Search } from "lucide-react";
import React, { useState } from "react";
import { cn } from "@/lib/cn";

import { CommandContext, useCommandContext } from "./command.context";
import { commandVariants, type CommandVariants } from "./command.variants";

export type CommandRootProps = CommandVariants &
  React.HTMLAttributes<HTMLDivElement> & {
    value?: string;
    onValueChange?: (value: string) => void;
  };

export const CommandRoot = ({
  children,
  className,
  size,
  value,
  onValueChange,
  ...props
}: CommandRootProps) => {
  const [internalSearch, setInternalSearch] = useState("");
  const search = value !== undefined ? value : internalSearch;
  const setSearch = onValueChange ?? setInternalSearch;

  const slots = commandVariants({ size });

  return (
    <CommandContext.Provider value={{ slots, search, setSearch }}>
      <div className={cn(slots.root(), className)} {...props}>
        {children}
      </div>
    </CommandContext.Provider>
  );
};

export type CommandDialogProps = React.ComponentProps<typeof BaseDialog.Root> & CommandRootProps;

export const CommandDialog = ({
  children,
  open,
  onOpenChange,
  defaultOpen,
  className,
  size,
  ...props
}: CommandDialogProps) => {
  const slots = commandVariants({ size });

  return (
    <BaseDialog.Root open={open} onOpenChange={onOpenChange} defaultOpen={defaultOpen}>
      <BaseDialog.Portal>
        <BaseDialog.Backdrop className={slots.dialogBackdrop()} />
        <BaseDialog.Popup className={cn(slots.dialogPopup(), className)}>
          <CommandRoot size={size} {...props}>
            {children}
          </CommandRoot>
        </BaseDialog.Popup>
      </BaseDialog.Portal>
    </BaseDialog.Root>
  );
};

export type CommandInputProps = Omit<React.InputHTMLAttributes<HTMLInputElement>, "value" | "onChange"> & {
  value?: string;
  onValueChange?: (value: string) => void;
};

export const CommandInput = ({ className, value, onValueChange, ...props }: CommandInputProps) => {
  const { slots, search, setSearch } = useCommandContext();

  const handleChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    setSearch(e.target.value);
    onValueChange?.(e.target.value);
  };

  return (
    <div className={slots.inputWrapper()}>
      <Search className="mr-2.5 h-4 w-4 shrink-0 text-muted-foreground" />
      <input
        className={cn(slots.input(), className)}
        value={value ?? search}
        onChange={handleChange}
        {...props}
      />
    </div>
  );
};

export type CommandListProps = React.HTMLAttributes<HTMLDivElement>;

export const CommandList = ({ className, ...props }: CommandListProps) => {
  const { slots } = useCommandContext();
  return <div className={cn(slots.list(), className)} {...props} />;
};

export type CommandEmptyProps = React.HTMLAttributes<HTMLDivElement>;

export const CommandEmpty = ({ className, ...props }: CommandEmptyProps) => {
  const { slots } = useCommandContext();
  return <div className={cn(slots.empty(), className)} {...props} />;
};

export type CommandGroupProps = React.HTMLAttributes<HTMLDivElement> & {
  heading?: React.ReactNode;
};

export const CommandGroup = ({ children, className, heading, ...props }: CommandGroupProps) => {
  const { slots } = useCommandContext();
  return (
    <div className={cn(slots.group(), className)} {...props}>
      {heading && <div className={slots.groupHeading()}>{heading}</div>}
      <div className={slots.groupItems()}>{children}</div>
    </div>
  );
};

export type CommandItemProps = React.HTMLAttributes<HTMLDivElement> & {
  disabled?: boolean;
  selected?: boolean;
  onSelect?: () => void;
};

export const CommandItem = ({
  children,
  className,
  disabled,
  selected,
  onSelect,
  onClick,
  ...props
}: CommandItemProps) => {
  const { slots } = useCommandContext();

  const handleClick = (e: React.MouseEvent<HTMLDivElement>) => {
    if (disabled) return;
    onSelect?.();
    onClick?.(e);
  };

  return (
    <div
      className={cn(slots.item(), className)}
      data-disabled={disabled ? "true" : undefined}
      data-selected={selected ? "true" : undefined}
      role="option"
      tabIndex={disabled ? -1 : 0}
      onClick={handleClick}
      {...props}
    >
      {children}
    </div>
  );
};

export type CommandShortcutProps = React.HTMLAttributes<HTMLSpanElement>;

export const CommandShortcut = ({ className, ...props }: CommandShortcutProps) => {
  const { slots } = useCommandContext();
  return <span className={cn(slots.shortcut(), className)} {...props} />;
};

export type CommandSeparatorProps = React.HTMLAttributes<HTMLDivElement>;

export const CommandSeparator = ({ className, ...props }: CommandSeparatorProps) => {
  const { slots } = useCommandContext();
  return <div className={cn(slots.separator(), className)} {...props} />;
};

/* eslint-disable perfectionist/sort-objects */

import { tv, type VariantProps } from "tailwind-variants";

export const commandVariants = tv({
  slots: {
    root: "command",
    dialogBackdrop: "command__dialog-backdrop",
    dialogPopup: "command__dialog-popup",
    inputWrapper: "command__input-wrapper",
    input: "command__input",
    list: "command__list",
    empty: "command__empty",
    group: "command__group",
    groupHeading: "command__group-heading",
    groupItems: "command__group-items",
    item: "command__item",
    shortcut: "command__shortcut",
    separator: "command__separator",
  },
  variants: {
    size: {
      sm: {
        root: "command--sm",
        inputWrapper: "px-3 py-2",
        item: "px-2 py-1.5 text-xs",
      },
      md: {
        root: "command--md",
      },
      lg: {
        root: "command--lg",
        inputWrapper: "px-4 py-3.5",
        item: "px-3 py-2.5 text-base",
      },
    },
  },
  defaultVariants: {
    size: "md",
  },
});

export type CommandVariants = VariantProps<typeof commandVariants>;

"use client";

import { createContext, useContext } from "react";

import { commandVariants } from "./command.variants";

export type CommandContextType = {
  slots: ReturnType<typeof commandVariants>;
  search: string;
  setSearch: (search: string) => void;
};

export const CommandContext = createContext<CommandContextType | null>(null);

export const useCommandContext = () => {
  const context = useContext(CommandContext);
  return context ?? { slots: commandVariants(), search: "", setSearch: () => {} };
};

.command {
  @apply flex h-full w-full flex-col overflow-hidden rounded-xl border border-border bg-background text-foreground shadow-lg;
}

.command__dialog-backdrop {
  @apply fixed inset-0 z-50 bg-black/80 backdrop-blur-xs transition-opacity duration-150 data-ending-style:opacity-0 data-starting-style:opacity-0;
}

.command__dialog-popup {
  @apply fixed top-1/2 left-1/2 z-50 w-full max-w-xl -translate-x-1/2 -translate-y-1/2 overflow-hidden rounded-xl border border-border bg-background p-0 shadow-2xl transition-[scale,opacity] duration-150 ease-out data-ending-style:scale-95 data-ending-style:opacity-0 data-starting-style:scale-95 data-starting-style:opacity-0;
}

.command__input-wrapper {
  @apply flex items-center border-b border-border px-3.5 py-3;
}

.command__input {
  @apply flex h-6 w-full rounded-md bg-transparent text-sm outline-none placeholder:text-muted-foreground disabled:cursor-not-allowed disabled:opacity-50;
}

.command__list {
  @apply max-h-[320px] overflow-y-auto overflow-x-hidden p-2;
}

.command__empty {
  @apply py-8 text-center text-sm text-muted-foreground;
}

.command__group {
  @apply overflow-hidden p-1 text-foreground;
}

.command__group-heading {
  @apply px-2 py-1.5 text-xs font-semibold text-muted-foreground tracking-wider uppercase;
}

.command__group-items {
  @apply flex flex-col gap-0.5;
}

.command__item {
  @apply relative flex cursor-pointer select-none items-center rounded-lg px-2.5 py-2 text-sm outline-none transition-colors hover:bg-accent hover:text-accent-foreground data-[selected=true]:bg-accent data-[selected=true]:text-accent-foreground data-[disabled=true]:pointer-events-none data-[disabled=true]:opacity-50;
}

.command__shortcut {
  @apply ml-auto text-xs tracking-widest text-muted-foreground font-mono bg-muted/60 px-1.5 py-0.5 rounded border border-border/50;
}

.command__separator {
  @apply -mx-1 my-1 h-px bg-border;
}

import {
  CommandDialog,
  CommandEmpty,
  CommandGroup,
  CommandInput,
  CommandItem,
  CommandList,
  CommandRoot,
  CommandSeparator,
  CommandShortcut,
} from "./command";

/**
 * @see https://ui.awaiden.com/llms.mdx/docs/components/command/content.md
 */
export const Command = {
  Dialog: CommandDialog,
  Empty: CommandEmpty,
  Group: CommandGroup,
  Input: CommandInput,
  Item: CommandItem,
  List: CommandList,
  Root: CommandRoot,
  Separator: CommandSeparator,
  Shortcut: CommandShortcut,
};

export {
  CommandDialog,
  CommandEmpty,
  CommandGroup,
  CommandInput,
  CommandItem,
  CommandList,
  CommandRoot,
  CommandSeparator,
  CommandShortcut,
};

export type {
  CommandDialogProps,
  CommandEmptyProps,
  CommandGroupProps,
  CommandInputProps,
  CommandItemProps,
  CommandListProps,
  CommandRootProps,
  CommandSeparatorProps,
  CommandShortcutProps,
} from "./command";

export { CommandContext, useCommandContext } from "./command.context";
export { type CommandVariants, commandVariants } from "./command.variants";
